typedef enum { DECISION_DENY = 0, DECISION_ALLOW = 1 } decision_t;

/* the single decision point: every rule lives here, nowhere else */
decision_t authz_decide(const subject_t *s, const char *action, const resource_t *r) {
    if (!s || !s->authenticated) return DECISION_DENY;            /* fail closed */
    return acl_allows(s->principal, action, r->id) ? DECISION_ALLOW : DECISION_DENY;
}

int handle_request(req_t *req) {
    if (authz_decide(req->subject, req->action, req->resource) != DECISION_ALLOW)
        return respond_403(req);                                  /* enforcement */
    return route_to_handler(req);
}
